const body = $input.first().json.body || {};
const question = String(body.question || '').trim();
if (!question) throw new Error('Question cannot be empty');
if (question.length > 2000) throw new Error('Question exceeds 2000 characters');
const settings = body.settings || {};
const rules = Array.isArray(body.rules) ? body.rules : [];
const jevRequest = {
  model: 'jev-latest',
  state: question,
  questions: {
    category: {
      type: 'choice',
      instructions: 'What kind of task is the user asking about?',
      criteria: {
        coding: 'Writing, debugging or explaining program code',
        data_analysis: 'Analyzing data, tables, statistics or spreadsheets',
        long_document_reasoning: 'Reading or summarizing long documents and reasoning over them',
        writing_editing: 'Writing, rewriting or proofreading text',
        translation: 'Translating text between languages',
        quick_factual_lookup: 'A short factual question with a brief answer',
        math: 'Solving mathematical or logical problems',
        image_understanding: 'Understanding or describing images',
        other: 'Anything that fits none of the other options'
      }
    },
    difficulty: {
      type: 'score',
      instructions: 'How demanding is this task for an AI model?',
      criteria: [
        'Trivial: a short, direct answer',
        'Easy: simple task, little reasoning',
        'Moderate: some reasoning or a few steps',
        'Hard: multi-step reasoning or specialist knowledge',
        'Very hard: deep expertise, long context or high complexity'
      ]
    },
    high_stakes: {
      type: 'noul',
      instructions: 'Does this involve a high-stakes legal, medical or financial decision or advice?'
    }
  }
};
return [{ json: { settings, rules, jevRequest } }];

const ans = $input.first().json.answers || {};
const prev = $('Validate and Build Request').first().json;
const cat = ans.category || {};
const diff = ans.difficulty || {};
const risk = ans.high_stakes || {};
const category = cat.choice || 'other';
const difficulty = Math.min(5, Math.max(1, Math.round(Number(diff.score ?? 2)) + 1));
const isHighRisk = Number(risk.noul ?? 0) > 0.5;
const confidence = Math.min(Number(cat.confidence ?? 0), Number(diff.confidence ?? 0));
const settings = prev.settings || {};
const threshold = Number(settings.confidence_threshold ?? 0.75);
const preference = settings.preference || 'best_quality';
const rule = prev.rules.find(r => r.category === category && r.difficulty_min <= difficulty && r.difficulty_max >= difficulty) || null;
let model = rule ? rule.model : null;
let reason = rule ? rule.reason : 'No routing rule is configured for this category and difficulty yet.';
const cheaper = rule ? rule.cheaper_alternative || null : null;
const stronger = rule ? rule.stronger_alternative || null : null;
if (isHighRisk) {
  model = stronger || model;
  reason = 'High-stakes topic detected (legal, medical or financial). Routed to the strongest option. Please verify with a professional.';
} else if (confidence < threshold) {
  model = stronger || model;
  reason = 'Confidence ' + confidence.toFixed(2) + ' is below your threshold ' + threshold + '. Routed to the stronger option for reliability.';
} else if (preference === 'cheaper' && cheaper) {
  model = cheaper;
  reason = 'Your preference is cheaper. Selected the economical option.';
}
return [{ json: { category, difficulty, risk: isHighRisk ? 'High' : 'Low', recommended_model: model, reason, confidence, cheaper_alternative: cheaper, stronger_alternative: stronger } }];
